Code.Terraform:
```hcl
# Attaches a data protection policy to an existing AgentCore log group
resource "aws_cloudwatch_log_data_protection_policy" "<example_resource_name>" {
  log_group_name = "<example_resource_name>"

  policy_document = jsonencode({
    Name    = "agentcore-data-protection-policy"
    Version = "2021-06-01"
    Statement = [
      {
        Sid            = "audit" # CRITICAL: required block, finds the sensitive terms
        DataIdentifier = ["arn:aws:dataprotection::aws:data-identifier/EmailAddress"]
        Operation = {
          Audit = {
            FindingsDestination = {}
          }
        }
      },
      {
        Sid            = "redact" # CRITICAL: the Deidentify block is what actually masks the data
        DataIdentifier = ["arn:aws:dataprotection::aws:data-identifier/EmailAddress"]
        Operation = {
          Deidentify = {
            MaskConfig = {}
          }
        }
      }
    ]
  })
}
